function getBangkokDate() {
  const d = new Date();
  const utc = d.getTime() + (d.getTimezoneOffset() * 60000);
  const bkk = new Date(utc + (3600000 * 7));
  const year = bkk.getFullYear();
  const month = String(bkk.getMonth() + 1).padStart(2, '0');
  const day = String(bkk.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function getBangkokDayOfWeek() {
  const d = new Date();
  const utc = d.getTime() + (d.getTimezoneOffset() * 60000);
  const bkk = new Date(utc + (3600000 * 7));
  return bkk.getDay(); // 0 = Sunday, 1 = Monday, 2 = Tuesday, 3 = Wednesday, 4 = Thursday, 5 = Friday, 6 = Saturday
}

function getBangkokHour() {
  const d = new Date();
  const utc = d.getTime() + (d.getTimezoneOffset() * 60000);
  const bkk = new Date(utc + (3600000 * 7));
  return bkk.getHours();
}


function formatThaiDateBkk(dateStr) {
  if (!dateStr || typeof dateStr !== 'string') return '';
  const parts = dateStr.split('-');
  if (parts.length !== 3) return dateStr;
  const y = parseInt(parts[0], 10);
  const m = parseInt(parts[1], 10) - 1;
  const d = parseInt(parts[2], 10);
  if (isNaN(y) || isNaN(m) || isNaN(d) || m < 0 || m > 11) return dateStr;
  return `${d} ${CRON_THAI_MONTHS[m]} ${y + 543}`;
}

function buildLarkCronDigestPayload(selectedDate, taskList, isAuto = true, orderMap = {}) {
  const thaiDate = formatThaiDateBkk(selectedDate) || selectedDate;
  let totalDueToday = 0;
  let totalInProg = 0;
  let totalOverdue = 0;
  let totalCompleted = 0;

  const memberSummaries = [];
  const dailyActiveTasks = new Map();

  const sortCronDailyList = (list, memberId, groupType) => {
    if (!Array.isArray(list) || list.length <= 1) return list || [];
    const orderKey = `${memberId}_${selectedDate}_${groupType}`;
    const memberKey = `${memberId}_${selectedDate}`;
    const fallbackKey = `${memberId}_${groupType}`;
    const orderList = (orderMap && typeof orderMap === 'object')
      ? (orderMap[orderKey] || orderMap[memberKey] || orderMap[fallbackKey] || orderMap[memberId] || [])
      : [];

    return [...list].sort((a, b) => {
      const idxA = orderList.indexOf(a.id);
      const idxB = orderList.indexOf(b.id);
      if (idxA !== -1 && idxB !== -1) return idxA - idxB;
      if (idxA !== -1) return -1;
      if (idxB !== -1) return 1;
      const rankA = a.priority === 'high' ? 1 : (a.priority === 'low' ? 3 : 2);
      const rankB = b.priority === 'high' ? 1 : (b.priority === 'low' ? 3 : 2);
      if (rankA !== rankB) return rankA - rankB;
      const dlA = a.deadline || a.date || '9999-99-99';
      const dlB = b.deadline || b.date || '9999-99-99';
      return dlA.localeCompare(dlB);
    });
  };

  const getTaskDetail = (t) => {
    if (!t) return "";
    let detail = (typeof t.note === "string" ? t.note : "").trim();
    if (!detail && typeof t.description === "string") {
      const desc = t.description.trim();
      const match = desc.match(/\((.*?)\)$/s);
      if (match && match[1] && match[1].trim()) {
        detail = match[1].trim();
      } else {
        const optKeys = Object.keys(CRON_TASK_OPTIONS);
        const parts = desc.split(',').map(p => p.trim());
        const isJustOpts = parts.length > 0 && parts.every(p => optKeys.includes(p));
        if (!isJustOpts && desc) {
          detail = desc;
        }
      }
    }
    return detail;
  };

  const formatItem = (t, indent = '      ') => {
    const opts = (Array.isArray(t.options) && t.options.length > 0)
      ? t.options.map(o => (CRON_TASK_OPTIONS[o] ? `${CRON_TASK_OPTIONS[o].icon} ${CRON_TASK_OPTIONS[o].name}` : o)).join(', ')
      : 'งานทั่วไป';
    const priorityPfx = t.priority === 'high' ? '🔥 [ด่วน] ' : (t.priority === 'low' ? '[ไม่รีบ] ' : '');
    let line = `${priorityPfx}**${t.title}** [${opts}]`;
    if (!t.isAllDay && (t.startTime || t.endTime)) {
      const timeSpan = (t.startTime && t.endTime) ? `${t.startTime} - ${t.endTime}` : (t.startTime ? `เริ่ม ${t.startTime}` : `ถึง ${t.endTime}`);
      line += ` (⏰ ${timeSpan} น.)`;
    }
    const detail = getTaskDetail(t);
    if (detail) {
      const detailLines = detail.split('\n').map(l => l.trim()).filter(Boolean);
      if (detailLines.length === 1) {
        line += `\n${indent}📝 *รายละเอียด:* ${detailLines[0]}`;
      } else if (detailLines.length > 1) {
        line += `\n${indent}📝 *รายละเอียด:*\n${indent}  ` + detailLines.join(`\n${indent}  `);
      }
    }
    return line;
  };

  CRON_TEAM_MEMBERS.forEach(member => {
    const mTasks = taskList.filter(t => t.assigneeIds && t.assigneeIds.includes(member.id));
    const dueToday = sortCronDailyList(mTasks.filter(t => t.deadline === selectedDate && t.status !== 'done'), member.id, 'due-today');
    const inProg = sortCronDailyList(mTasks.filter(t => {
      const s = t.date || t.deadline; const e = t.deadline || t.date;
      return s <= selectedDate && selectedDate <= e && t.deadline !== selectedDate && t.status !== 'done';
    }), member.id, 'in-progress');
    const overdue = sortCronDailyList(mTasks.filter(t => t.deadline < selectedDate && t.status !== 'done'), member.id, 'overdue');
    const completed = sortCronDailyList(mTasks.filter(t => {
      if (t.status !== 'done') return false;
      const s = t.date || t.deadline; const e = t.deadline || t.date;
      return (s <= selectedDate && selectedDate <= e) || t.deadline === selectedDate;
    }), member.id, 'completed');

    [...dueToday, ...inProg, ...overdue, ...completed].forEach(t => {
      dailyActiveTasks.set(t.id, t);
    });

    totalDueToday += dueToday.length;
    totalInProg += inProg.length;
    totalOverdue += overdue.length;
    totalCompleted += completed.length;

    const mTotal = dueToday.length + inProg.length + overdue.length + completed.length;
    if (mTotal > 0) {
      let taskLines = [];
      if (dueToday.length > 0) {
        if (dueToday.length === 1) {
          taskLines.push(`  • 🚨 **ต้องส่งวันนี้:** 1. ` + formatItem(dueToday[0], '    '));
        } else {
          taskLines.push(`  • 🚨 **ต้องส่งวันนี้ (${dueToday.length} งาน):**\n` + dueToday.map((t, idx) => `    ${idx + 1}. ` + formatItem(t, '       ')).join('\n'));
        }
      }
      if (inProg.length > 0) {
        if (inProg.length === 1) {
          taskLines.push(`  • ⚡ **กำลังทำอยู่:** 1. ` + formatItem(inProg[0], '    '));
        } else {
          taskLines.push(`  • ⚡ **กำลังทำอยู่ (${inProg.length} งาน):**\n` + inProg.map((t, idx) => `    ${idx + 1}. ` + formatItem(t, '       ')).join('\n'));
        }
      }
      if (overdue.length > 0) {
        if (overdue.length === 1) {
          taskLines.push(`  • ⚠️ **งานค้างเกินกำหนด:** 1. ` + formatItem(overdue[0], '    '));
        } else {
          taskLines.push(`  • ⚠️ **งานค้างเกินกำหนด (${overdue.length} งาน):**\n` + overdue.map((t, idx) => `    ${idx + 1}. ` + formatItem(t, '       ')).join('\n'));
        }
      }
      if (completed.length > 0) {
        if (completed.length === 1) {
          taskLines.push(`  • ✅ **ทำเสร็จแล้ว:** 1. ` + formatItem(completed[0], '    '));
        } else {
          taskLines.push(`  • ✅ **ทำเสร็จแล้ว (${completed.length} งาน):**\n` + completed.map((t, idx) => `    ${idx + 1}. ` + formatItem(t, '       ')).join('\n'));
        }
      }

      memberSummaries.push(
        `**${member.avatar} ${member.name}** (เสร็จ ${completed.length}/${mTotal} งาน):\n` + taskLines.join('\n')
      );
    }
  });

  const typeCounts = {};
  dailyActiveTasks.forEach(t => {
    if (Array.isArray(t.options)) {
      t.options.forEach(opt => {
        typeCounts[opt] = (typeCounts[opt] || 0) + 1;
      });
    }
  });
  const typeSummaryList = Object.entries(typeCounts)
    .sort((a, b) => b[1] - a[1])
    .map(([opt, count]) => {
      const conf = CRON_TASK_OPTIONS[opt] || { icon: '🏷️', name: opt };
      return `${conf.icon} ${conf.name} (${count})`;
    });
  const typeSummaryText = typeSummaryList.length > 0
    ? `**🎬 ลักษณะงานในวันนี้:** ${typeSummaryList.join(' • ')}`
    : '';

  const appUrl = 'https://team-taskflow.iydcrmvjt.workers.dev';
  let breakdownText = memberSummaries.length > 0 
    ? memberSummaries.join('\n\n')
    : '🎉 ไม่มีภาระงานค้างสำหรับสมาชิกในวันนี้';

  const cardElements = [
    {
      tag: "div",
      fields: [
        {
          is_short: true,
          text: { tag: "lark_md", content: `**🚨 ต้องส่งวันนี้:** ${totalDueToday} งาน\n**⚡ กำลังทำอยู่:** ${totalInProg} งาน` }
        },
        {
          is_short: true,
          text: { tag: "lark_md", content: `**⚠️ งานค้างเกินกำหนด:** ${totalOverdue} งาน\n**✅ เสร็จสิ้นแล้ว:** ${totalCompleted} งาน` }
        }
      ]
    }
  ];

  if (typeSummaryText) {
    cardElements.push({
      tag: "div",
      text: { tag: "lark_md", content: typeSummaryText }
    });
  }

  cardElements.push(
    { tag: "hr" },
    {
      tag: "div",
      text: { tag: "lark_md", content: `**📋 รายละเอียดงานรายบุคคล (พร้อมลักษณะงานและเนื้อหา):**\n\n${breakdownText}` }
    },
    {
      tag: "action",
      actions: [
        {
          tag: "button",
          text: { tag: "plain_text", content: "🚀 ไปที่บอร์ดงาน Team TaskFlow" },
          type: "primary",
          url: appUrl
        }
      ]
    }
  );

  return {
    msg_type: "interactive",
    card: {
      config: { wide_screen_mode: true, enable_forward: true },
      header: {
        template: isAuto ? "turquoise" : "orange",
        title: { tag: "plain_text", content: `${isAuto ? '⏰ สรุปงานประจำวันอัตโนมัติ (09:00 น. จันทร์–ศุกร์)' : '🧪 ทดสอบสรุปงานประจำวัน (09:00 น.)'}: ${thaiDate}` }
      },
      elements: cardElements
    }
  };
}

async function handleScheduledDailyDigest(env, event, isManual = false) {
  // 1. Strict Day-of-Week validation (Bangkok Time UTC+7)
  // Only Monday (1) through Friday (5) are allowed.
  // Sunday (0) and Saturday (6) MUST BE SKIPPED for automated cron!
  const bkkDay = getBangkokDayOfWeek();
  const isWeekend = (bkkDay === 0 || bkkDay === 6);
  const dayNames = ['วันอาทิตย์', 'วันจันทร์', 'วันอังคาร', 'วันพุธ', 'วันพฤหัสบดี', 'วันศุกร์', 'วันเสาร์'];

  if (!isManual && isWeekend) {
    const todayStr = getBangkokDate();
    console.log(`[Lark Cron] Skipped: Today is ${dayNames[bkkDay]} (Bangkok time). Automated daily digest runs Mon-Fri only.`);
    const db = getDb(env);
    if (db) {
      try {
        const record = JSON.stringify({
          timestamp: new Date().toISOString(),
          bkkDate: formatThaiDateBkk(todayStr),
          status: "skipped_weekend",
          reason: `งดส่งอัตโนมัติเนื่องจากเป็น${dayNames[bkkDay]} (ระบบส่งเฉพาะวันจันทร์–ศุกร์)`
        });
        await db.prepare("INSERT INTO meta (key, value) VALUES ('last_cron_digest', ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value").bind(record).run();
      } catch(e) {}
    }
    return {
      success: false,
      reason: "weekend_skipped",
      dayOfWeek: bkkDay,
      dayName: dayNames[bkkDay],
      message: `วันนี้เป็น${dayNames[bkkDay]} ระบบงดส่งการแจ้งเตือนอัตโนมัติในวันเสาร์-อาทิตย์ (ส่งเฉพาะวันจันทร์-ศุกร์)`
    };
  }

  const db = getDb(env);
  let webhookUrl = (env && env.LARK_WEBHOOK_URL) || "";
  let cronEnabled = true;

  if (db) {
    try {
      await ensureTable(db);
      const row = await db.prepare("SELECT value FROM meta WHERE key = 'lark_config'").first();
      if (row && row.value) {
        const parsed = JSON.parse(row.value);
        if (parsed.webhookUrl) webhookUrl = parsed.webhookUrl;
        if (parsed.cronAutoDigest !== undefined) cronEnabled = parsed.cronAutoDigest;
      }
    } catch (e) {
      console.warn("Error fetching lark_config for scheduled cron:", e);
    }
  }

  if (!webhookUrl || (!isManual && !cronEnabled)) {
    console.log("Automated daily digest skipped: webhookUrl not set or cron disabled.");
    return { success: false, reason: "disabled_or_no_webhook" };
  }

  let tasks = [];
  if (db) {
    try {
      const res = await db.prepare("SELECT * FROM tasks").all();
      tasks = (res && res.results) ? res.results.map(row => {
        let options = []; try { options = JSON.parse(row.options); } catch(e) {}
        let assigneeIds = []; try { assigneeIds = JSON.parse(row.assignee_ids); } catch(e) {}
        return {
          id: row.id,
          title: row.title,
          options: options,
          note: row.note || "",
          description: row.description || "",
          date: row.date,
          deadline: row.deadline,
          isAllDay: row.is_all_day === undefined || row.is_all_day === null ? true : Boolean(row.is_all_day),
          startTime: row.start_time || "",
          endTime: row.end_time || "",
          status: row.status || "todo",
          assigneeIds: assigneeIds,
          priority: row.priority || "normal",
          color: row.color || "blue"
        };
      }) : [];
    } catch (e) {
      console.error("Error reading tasks for cron digest:", e);
    }
  }

  let orderMap = {};
  if (db) {
    try {
      const oRow = await db.prepare("SELECT value FROM meta WHERE key = 'daily_order'").first();
      if (oRow && oRow.value) orderMap = JSON.parse(oRow.value);
    } catch(e) {}
  }

  const todayStr = getBangkokDate();
  const cardPayload = buildLarkCronDigestPayload(todayStr, tasks, true, orderMap);

  let sendResult = null;
  let sendError = null;
  let isSuccess = false;
  let httpStatus = 0;

  for (let attempt = 1; attempt <= 2; attempt++) {
    try {
      const res = await fetch(webhookUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json; charset=utf-8" },
        body: JSON.stringify(cardPayload)
      });
      httpStatus = res.status;
      const result = await res.json().catch(() => ({}));
      sendResult = result;
      // Lark success is HTTP 200 AND (code === 0 or StatusCode === 0)
      isSuccess = res.ok && (!result || result.code === 0 || result.StatusCode === 0);
      if (isSuccess) break;
      console.warn(`[Lark 09:00 Cron] Attempt ${attempt} returned non-zero code:`, result);
    } catch(err) {
      sendError = err;
      console.warn(`[Lark 09:00 Cron] Attempt ${attempt} network error:`, err);
    }
    if (attempt < 2) await new Promise(r => setTimeout(r, 2000));
  }

  // Record last cron run in meta table
  if (db) {
    try {
      const record = JSON.stringify({
        timestamp: new Date().toISOString(),
        bkkDate: formatThaiDateBkk(todayStr),
        totalTasks: tasks.length,
        status: isSuccess ? "success" : "failed",
        code: (sendResult && (sendResult.code !== undefined ? sendResult.code : sendResult.StatusCode)) ?? (isSuccess ? 0 : -1),
        msg: (sendResult && (sendResult.msg || sendResult.StatusMessage)) || (sendError ? sendError.message : (isSuccess ? "OK" : `HTTP ${httpStatus}`))
      });
      await db.prepare("INSERT INTO meta (key, value) VALUES ('last_cron_digest', ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value").bind(record).run();
    } catch(e) {
      console.warn("Error recording last_cron_digest:", e);
    }
  }

  console.log("Automated 09:00 Lark daily digest dispatched:", httpStatus, sendResult);
  return { success: isSuccess, status: httpStatus, result: sendResult, error: sendError ? sendError.message : undefined };
}


function buildLarkEveningEODPayload(selectedDate, taskList, isAuto = true) {
  const thaiDate = formatThaiDateBkk(selectedDate) || selectedDate;
  
  const inProgTasks = taskList.filter(t => t.status === 'in-progress');
  const overdueTasks = taskList.filter(t => t.status !== 'done' && t.deadline && t.deadline < selectedDate);
  const dueTodayPending = taskList.filter(t => t.status === 'todo' && t.deadline === selectedDate);
  const completedToday = taskList.filter(t => {
    if (t.status !== 'done') return false;
    const s = t.date || t.deadline; const e = t.deadline || t.date;
    return (s <= selectedDate && selectedDate <= e) || t.deadline === selectedDate;
  });

  const getTaskDetail = (t) => {
    if (!t) return "";
    let detail = (typeof t.note === "string" ? t.note : "").trim();
    if (!detail && typeof t.description === "string") {
      const desc = t.description.trim();
      const match = desc.match(/\((.*?)\)$/s);
      if (match && match[1] && match[1].trim()) {
        detail = match[1].trim();
      } else {
        const optKeys = Object.keys(CRON_TASK_OPTIONS);
        const parts = desc.split(',').map(p => p.trim());
        const isJustOpts = parts.length > 0 && parts.every(p => optKeys.includes(p));
        if (!isJustOpts && desc) {
          detail = desc;
        }
      }
    }
    return detail;
  };

  const formatItem = (t, indent = '      ') => {
    const opts = (Array.isArray(t.options) && t.options.length > 0)
      ? t.options.map(o => (CRON_TASK_OPTIONS[o] ? `${CRON_TASK_OPTIONS[o].icon} ${CRON_TASK_OPTIONS[o].name}` : o)).join(', ')
      : 'งานทั่วไป';
    let line = `**${t.title}** [${opts}]`;
    if (!t.isAllDay && (t.startTime || t.endTime)) {
      const timeSpan = (t.startTime && t.endTime) ? `${t.startTime} - ${t.endTime}` : (t.startTime ? `เริ่ม ${t.startTime}` : `ถึง ${t.endTime}`);
      line += ` (⏰ ${timeSpan} น.)`;
    }
    const detail = getTaskDetail(t);
    if (detail) {
      const detailLines = detail.split('\n').map(l => l.trim()).filter(Boolean);
      if (detailLines.length === 1) {
        line += `\n${indent}📝 *รายละเอียด:* ${detailLines[0]}`;
      } else if (detailLines.length > 1) {
        line += `\n${indent}📝 *รายละเอียด:*\n${indent}  ` + detailLines.join(`\n${indent}  `);
      }
    }
    return line;
  };

  const memberSummaries = [];
  CRON_TEAM_MEMBERS.forEach(member => {
    const mTasks = taskList.filter(t => t.assigneeIds && t.assigneeIds.includes(member.id));
    const mInProg = mTasks.filter(t => t.status === 'in-progress');
    const mOverdue = mTasks.filter(t => t.status !== 'done' && t.deadline && t.deadline < selectedDate);
    const mDueToday = mTasks.filter(t => t.status === 'todo' && t.deadline === selectedDate);
    const mDone = mTasks.filter(t => {
      if (t.status !== 'done') return false;
      const s = t.date || t.deadline; const e = t.deadline || t.date;
      return (s <= selectedDate && selectedDate <= e) || t.deadline === selectedDate;
    });

    const pendingTotal = mInProg.length + mOverdue.length + mDueToday.length;
    if (pendingTotal > 0 || mDone.length > 0) {
      let lines = [];
      if (mInProg.length > 0) {
        lines.push(`  • ⚡ **กำลังทำอยู่ (${mInProg.length} งาน):**\n    - ` + mInProg.map(t => formatItem(t, '      ')).join('\n    - '));
      }
      if (mOverdue.length > 0) {
        lines.push(`  • ⚠️ **ค้างเกินกำหนด (${mOverdue.length} งาน):**\n    - ` + mOverdue.map(t => formatItem(t, '      ')).join('\n    - '));
      }
      if (mDueToday.length > 0) {
        lines.push(`  • 📋 **ครบกำหนดวันนี้แต่ยังไม่เริ่ม (${mDueToday.length} งาน):**\n    - ` + mDueToday.map(t => formatItem(t, '      ')).join('\n    - '));
      }
      if (mDone.length > 0) {
        lines.push(`  • ✅ **เสร็จสิ้นแล้ววันนี้:** ${mDone.length} งาน`);
      }

      if (pendingTotal > 0) {
        memberSummaries.push(`**${member.avatar} ${member.name}** (ค้างอัปเดต ${pendingTotal} งาน):\n` + lines.join('\n'));
      } else {
        memberSummaries.push(`**${member.avatar} ${member.name}**: 🎉 เคลียร์งานวันนี้เสร็จครบหมดแล้ว (${mDone.length} งาน ✅)`);
      }
    }
  });

  const appUrl = 'https://team-taskflow.iydcrmvjt.workers.dev';
  const breakdownText = memberSummaries.length > 0
    ? memberSummaries.join('\n\n')
    : '🎉 ยอดเยี่ยมมาก! ไม่มีงานค้างในระบบสำหรับวันนี้';

  const cardElements = [
    {
      tag: "div",
      text: {
        tag: "lark_md",
        content: "📢 **ใกล้หมดเวลาทำการแล้วครับ (18:00 น.)**\nขอความร่วมมือทีมงานทุกคนช่วยตรวจสอบและอัปเดตสถานะงานในระบบ TaskFlow ให้เป็นปัจจุบัน:\n• งานไหนที่ถ่ายทำหรือตัดต่อเสร็จแล้ว กรุณาย้ายไป **\"Done ✅\"**\n• งานไหนยังไม่เสร็จหรือติดปัญหา กรุณาใส่โน้ตแจ้งความคืบหน้าไว้ได้เลยครับ"
      }
    },
    { tag: "hr" },
    {
      tag: "div",
      fields: [
        {
          is_short: true,
          text: { tag: "lark_md", content: `**⚡ กำลังทำอยู่ (In Progress):** ${inProgTasks.length} งาน\n**⚠️ ค้างเกินกำหนด (Overdue):** ${overdueTasks.length} งาน` }
        },
        {
          is_short: true,
          text: { tag: "lark_md", content: `**📋 ถึงกำหนดวันนี้แต่ยังไม่เริ่ม:** ${dueTodayPending.length} งาน\n**✅ เสร็จสิ้นแล้ววันนี้:** ${completedToday.length} งาน` }
        }
      ]
    },
    { tag: "hr" },
    {
      tag: "div",
      text: { tag: "lark_md", content: `**👥 สรุปงานค้างรายบุคคล (โปรดอัปเดตสถานะก่อนเลิกงาน):**\n\n${breakdownText}` }
    },
    {
      tag: "action",
      actions: [
        {
          tag: "button",
          text: { tag: "plain_text", content: "🚀 เปิด TaskFlow เพื่ออัปเดตสถานะงาน" },
          type: "primary",
          url: appUrl
        }
      ]
    }
  ];

  return {
    msg_type: "interactive",
    card: {
      config: { wide_screen_mode: true, enable_forward: true },
      header: {
        template: isAuto ? "orange" : "carmine",
        title: { tag: "plain_text", content: `${isAuto ? '🔔 แจ้งเตือนเช็กสถานะงานประจำวัน (18:00 น. จันทร์–ศุกร์)' : '🧪 ทดสอบแจ้งเตือนสถานะงาน (18:00 น.)'}: ${thaiDate}` }
      },
      elements: cardElements
    }
  };
}

